<?php
namespace App\Http\Controllers;use App\Models\{CommitteeMeeting,CommitteeMinute};use App\Services\CommitteeMinuteService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class CommitteeMinuteController extends Controller{public function generate(CommitteeMeeting $meeting,Request $request,CommitteeMinuteService $service){$service->generate($meeting,$request->user()->id);return back()->with('success','Borrador del acta generado.');}public function approve(CommitteeMinute $minute,Request $request,CommitteeMinuteService $service){$data=$request->validate(['observations'=>'nullable|string|max:2000']);$service->approve($minute,$request->user()->id,$data['observations']??'');return back()->with('success','Acta aprobada.');}public function finalize(CommitteeMinute $minute,Request $request,CommitteeMinuteService $service){$service->finalize($minute,$request->user()->id);return back()->with('success','Acta finalizada y registrada en Gestión Documental.');}public function download(CommitteeMinute $minute){abort_unless($minute->document_path&&Storage::disk('public')->exists($minute->document_path),404);return Storage::disk('public')->download($minute->document_path);}}
